            try {
                $printers = Get-Printer -ErrorAction Stop | Select-Object Name, DriverName, PrinterStatus, PortName
                $default = (Get-WmiObject -Query " SELECT * FROM Win32_Printer WHERE Default=$true ").Name
                $result = @()
                foreach ($p in $printers) {
                    $statusStr = "Ready"
                    if ($p.PrinterStatus -eq 1) { $statusStr = "Other" }
                    elseif ($p.PrinterStatus -eq 2) { $statusStr = "Error/Offline" }
                    elseif ($p.PrinterStatus -eq 3) { $statusStr = "Ready" }
